'use strict';
const ZSND_B64 = {
  z_alert_1: '',
  z_attack_1: '',
  z_attack_2: '',
  z_death_1: '',
  z_idle_1: '',
  z_idle_10: '',
  z_idle_11: '',
  z_idle_12: '',
  z_idle_13: '',
  z_idle_14: '',
  z_idle_2: '',
  z_idle_3: '',
  z_idle_4: '',
  z_idle_5: '',
  z_idle_6: '',
  z_idle_7: '',
  z_idle_8: '',
  z_idle_9: '',
  z_rage: '',
  z_roar: '',
  z_scream: ''
};
/* ---------- 15б. Голоса зомби (v0.32): записи из пака, звук из точки, лимит голосов, гул толпы ----------
   Записи лежат в ZSND_B64 (z_idle_1…14, z_attack_1–2, z_death_1, z_alert_1, z_roar, z_rage, z_scream),
   декодирует их общий loadRealSounds. Все голоса идут через свою шину ZV.bus → Sound.master,
   громкость шины — «Голоса зомби» в настройках. Хуки в старом коде: укус (updateZombies),
   смерть (damageZombie), крик/рёв (SFX.scream/roar получают зомби), кадр (zvTick в frame). */
const ZV = { vol: lsGet('zvol', 1), bus: null, n: 0, gap: 0, tick: 0, atkGap: 0, deathGap: 0, alertGap: 0, last: {},
  bed: null, bedG: null, bedTry: 0, crowd: 0 };
const ZV_MAX = 4;            // одновременно звучащих голосов (крики и рёв проходят сверх лимита)
const ZV_HEAR = 18;          // дальше не слышно
const ZV_IDLE_R = 13;        // бормочут только зомби ближе этого к кому-то из игроков
const ZV_PITCH = { walker: 1, armored: 0.94, runner: 1.14, fat: 0.8, brute: 0.74, riot: 0.92, screamer: 1.08, spitter: 1.04, warden: 0.7 };
const zvRate = z => (z && ZV_PITCH[z.type]) || 1;
function zvBus() {
  if (!ZV.bus && Sound.ctx && Sound.master) { ZV.bus = Sound.ctx.createGain(); ZV.bus.gain.value = ZV.vol; ZV.bus.connect(Sound.master); }
  return ZV.bus;
}
function zvSetVol(v) { ZV.vol = v; lsSet('zvol', v); if (ZV.bus) ZV.bus.gain.value = v; }
// случайный вариант name_1..n, не тот же, что в прошлый раз
function zvPick(name) {
  if (Sound.buf[name]) return Sound.buf[name];
  const n = []; for (let i = 1; Sound.buf[name + '_' + i]; i++) n.push(i);
  if (!n.length) return null;
  let k = n[Math.floor(Math.random() * n.length)];
  if (n.length > 1 && k === ZV.last[name]) k = n[(n.indexOf(k) + 1 + Math.floor(Math.random() * (n.length - 1))) % n.length];
  ZV.last[name] = k; return Sound.buf[name + '_' + k];
}
// «ухо» — ближайший игрок (в коопе каждый слышит своих зомби)
function zvEar(x, z) {
  let best = null, bd = Infinity;
  for (const p of players) { const d = (p.x - x) ** 2 + (p.z - z) ** 2; if (d < bd) { bd = d; best = p; } }
  return best ? { p: best, d: Math.sqrt(bd) } : null;
}
// Проиграть голос в точке x,z: тише и глуше вдали, слева — слева. o.force — мимо лимита, o.hear/o.near — дальность
function zvPlay(name, x, z, vol = 1, rate = 1, o = {}) {
  if (!soundOn() || ZV.vol <= 0 || !zvBus()) return false;
  if (!o.force && ZV.n >= ZV_MAX) return false;
  const b = zvPick(name); if (!b) return false;
  const hear = o.hear || ZV_HEAR, near = o.near || 4;
  let d = 0, pan = 0;
  if (x !== undefined && x !== null) {
    const e = zvEar(x, z); if (!e) return false;
    d = e.d; pan = clamp(scrOff(x - e.p.x, z - e.p.z)[0] / 7, -1, 1) * 0.75;
  }
  if (d > hear) return false;
  const c = Sound.ctx, t = c.currentTime, k = 1 - d / hear;
  const src = c.createBufferSource(); src.buffer = b;
  src.playbackRate.value = rate * (1 + (Math.random() * 2 - 1) * 0.08);
  const f = c.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = 900 + 15000 * k * k; f.Q.value = 0.5;
  const g = c.createGain(); g.gain.value = vol * (0.85 + Math.random() * 0.3) / (1 + (d / near) ** 2);
  src.connect(f); f.connect(g);
  if (c.createStereoPanner) { const sp = c.createStereoPanner(); sp.pan.value = pan; g.connect(sp); sp.connect(ZV.bus); }
  else g.connect(ZV.bus);
  ZV.n++; src.onended = () => { ZV.n = Math.max(0, ZV.n - 1); };
  src.start(t); return true;
}
// укус: у каждого зомби свой откат, общий — 0.2 с
function zvAttack(z) {
  if (!z || z.type === 'hound' || G.state !== 'play') return;
  if ((z.vAtk || 0) > G.t || ZV.atkGap > 0) return;
  z.vAtk = G.t + rnd(2, 3.5); ZV.atkGap = 0.2;
  zvPlay('z_attack', z.x, z.z, 1, zvRate(z), { force: true });
}
// смерть: голос не на каждое убийство, иначе орда заглушит стрельбу
function zvDeath(z) {
  if (!z || z.type === 'hound' || ZOMBIES[z.type].fat) return;
  if (z.type === 'warden') { zvPlay('z_roar', z.x, z.z, 1.1, 0.62, { force: true, hear: 40, near: 8 }); return; }
  if (ZV.deathGap > 0 || Math.random() > 0.4) return;
  ZV.deathGap = 0.4;
  zvPlay('z_death', z.x, z.z, 0.9, zvRate(z));
}
// крик кричащего и вызов охраны начальником; рёв громилы и начальника — записи вместо синтеза
{
  const synthScream = SFX.scream, synthRoar = SFX.roar;
  SFX.scream = z => {
    if (!soundOn()) return;
    const boss = z && z.type === 'warden';
    if (zvPlay(boss ? 'z_rage' : 'z_scream', z ? z.x : null, z ? z.z : null, boss ? 1 : 0.95, boss ? 0.8 : rnd(0.95, 1.05), { force: true, hear: 30, near: 7 })) return;
    synthScream();
  };
  SFX.roar = z => {
    if (!soundOn()) return;
    if (zvPlay('z_roar', z ? z.x : null, z ? z.z : null, 1, z ? zvRate(z) : 0.7, { force: true, hear: 30, near: 7 })) return;
    synthRoar();
  };
}
// Гул толпы: петля 8 с из наложенных бормотаний, глухая; громче, чем больше зомби рядом
function zvBuildBed() {
  const ids = []; for (let i = 1; Sound.buf['z_idle_' + i]; i++) ids.push(Sound.buf['z_idle_' + i]);
  if (ids.length < 8) return null;
  const c = Sound.ctx, sr = c.sampleRate, len = Math.floor(sr * 8), out = c.createBuffer(2, len, sr);
  for (let ch = 0; ch < 2; ch++) {
    const o = out.getChannelData(ch);
    for (let k = 0; k < 16; k++) {
      const s = ids[Math.floor(Math.random() * ids.length)].getChannelData(0);
      const r = 0.75 + Math.random() * 0.4, g = 0.3 + Math.random() * 0.4, off = Math.floor(Math.random() * len), n = Math.floor(s.length / r);
      for (let i = 0; i < n; i++) o[(off + i) % len] += s[Math.floor(i * r)] * g;
    }
  }
  let m = 0; for (let ch = 0; ch < 2; ch++) { const o = out.getChannelData(ch); for (let i = 0; i < len; i++) m = Math.max(m, Math.abs(o[i])); }
  if (m > 0) for (let ch = 0; ch < 2; ch++) { const o = out.getChannelData(ch); for (let i = 0; i < len; i++) o[i] *= 0.6 / m; }
  return out;
}
function zvBed(dt, play) {
  if (!ZV.bed) {
    if (!play || !zvBus() || (ZV.bedTry -= dt) > 0) return;
    ZV.bedTry = 1; const buf = zvBuildBed(); if (!buf) return;
    const c = Sound.ctx, src = c.createBufferSource(); src.buffer = buf; src.loop = true;
    const f = c.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = 650; f.Q.value = 0.4;
    ZV.bedG = c.createGain(); ZV.bedG.gain.value = 0;
    src.connect(f); f.connect(ZV.bedG); ZV.bedG.connect(ZV.bus); src.start(); ZV.bed = src;
  }
  const want = play ? 0.32 * Math.pow(Math.min(1, Math.max(0, ZV.crowd - 6) / 40), 0.8) : 0;
  const gn = ZV.bedG.gain, cur = gn.value; gn.value = cur + (want - cur) * Math.min(1, dt * 1.5);
}
// каждый кадр: раз в 0.25 с выбираем, кто из ближних зомби подаст голос
function zvTick(dt) {
  if (!Sound.ctx || !soundOn()) return;
  const play = G.state === 'play' && !G.paused && players.length > 0;
  zvBed(dt, play);
  if (!play) return;
  ZV.gap -= dt; ZV.atkGap -= dt; ZV.deathGap -= dt; ZV.alertGap -= dt;
  if ((ZV.tick -= dt) > 0) return;
  const step = 0.25 - ZV.tick; ZV.tick = 0.25;
  let cand = null, cd = Infinity, crowd = 0;
  for (const z of zombies) {
    if (z.dead || z.type === 'hound') continue;
    const e = zvEar(z.x, z.z); if (!e) break;
    if (e.d < 16) crowd++;
    if (z.type === 'runner' && !z.vAlert && e.d < 10) {           // бегун заметил — рычит один раз
      z.vAlert = true;
      if (ZV.alertGap <= 0 && zvPlay('z_alert', z.x, z.z, 0.9, zvRate(z))) ZV.alertGap = 1.5;
    }
    if (z.vT === undefined) z.vT = rnd(1.5, 9);
    if ((z.vT -= step * (z.rageT > 0 ? 2 : 1)) > 0) continue;      // разъярённые криком бормочут чаще
    if (e.d > ZV_IDLE_R) { z.vT = rnd(2, 5); continue; }
    if (e.d < cd) { cd = e.d; cand = z; }
  }
  ZV.crowd = crowd;
  if (cand && ZV.gap <= 0 && ZV.n < ZV_MAX - 1) {                 // одно место всегда держим для укуса
    if (zvPlay('z_idle', cand.x, cand.z, 0.8, zvRate(cand))) ZV.gap = rnd(0.5, 1.4);
    cand.vT = rnd(7, 16);
  }
}
